// <static:typescript-logic>
async function executeToolsImpl<Id extends TemplateId>(
  calls: Iterable<ToolCall>,
  tools: Tools<Id>,
  executor: ToolExecutor<Id>,
): Promise<ReadonlyArray<ToolCallResponse>> {
  return Promise.all(
    Array.from(calls).map(async (call) => {
      const { callId, toolName, stringifiedInput } = call;
      const tool = (tools as Record<string, Tool<unknown, unknown>>)[toolName];
      if (!tool) {
        throw new Error(`Tool not found: ${toolName}`);
      }
      const impl = (
        executor as Record<string, (input: unknown) => Promise<unknown>>
      )[toolName];
      if (!impl) {
        throw new Error(`Tool implementation not found: ${toolName}`);
      }
      let stringifiedOutput: string;
      try {
        const input = tool.inputSchema.parse(JSON.parse(stringifiedInput));
        const output = tool.outputSchema.parse(await impl(input));
        stringifiedOutput = JSON.stringify(output);
      } catch (e) {
        const err = new Error(
          "Tool call failed: "
            .concat(JSON.stringify({ callId, toolName }))
            .concat(" — ")
            .concat(String(e)),
        );
        (err as { cause?: unknown }).cause = e;
        throw err;
      }
      return { callId, stringifiedOutput };
    }),
  );
}

function newPromptsImpl(templates: Spec.Templates): Prompts {
  const result: Record<string, Record<string, Template<TemplateId>>> = {};
  for (const template of Object.values(templates.templates)) {
    const id = [template.namespace, template.name].join(":") as TemplateId;
    const namespace = uncapitalize(template.namespace);
    const name = uncapitalize(template.name);
    (result[namespace] ??= {})[name] = {
      render: (input: unknown): Prompt<TemplateId> =>
        renderTemplate(id, templates, input as Input<TemplateId>),
    };
  }
  const entries = Object.entries(result);
  if (entries.length === 1) {
    return entries[0]![1] as unknown as Prompts;
  } else {
    return result as unknown as Prompts;
  }
}

/**
 * Use this with external frameworks that support template override injection
 * for experimentation or A/B testing.
 *
 * When using overrides, inject the resulting {@link Prompts} instance as a
 * dependency rather than relying on the global {@link prompts} variable.
 */
export const templateOverrider: {
  readonly templatesData: unknown;
  readonly applyOverrides: (overrides: unknown) => Prompts;
} = {
  templatesData: TEMPLATES_DATA,
  applyOverrides: (overrides: unknown) => {
    const templatesData = templatesSchema.parse(
      typeof overrides === "object"
        ? { ...TEMPLATES_DATA, ...overrides }
        : overrides,
    );
    if (templatesData.signature !== TEMPLATES_DATA.signature) {
      throw new Error("Signature mismatch");
    }
    return newPromptsImpl(templatesData);
  },
} as const;

function renderTemplate<Id extends TemplateId>(
  templateId: TemplateId,
  templates: Spec.Templates,
  input: Input<Id>,
): Prompt<Id> {
  const template = templates.templates[templateId];
  if (!template) {
    throw new Error(`Template not found: ${templateId}`);
  }
  const { input: inputSchema, output: outputSchema } = zodSchemas[templateId]!;
  input = (inputSchema as z.ZodType<Input<Id>>).parse(input);
  const { contents, snippets } = template;
  let meta: Meta;
  let systemMessage: string;
  let userMessage: string;
  let examples: readonly FewShotExample[];
  if (contents.kind === "no-variants") {
    const { content } = contents;
    meta = content.meta as Meta;
    systemMessage = renderBody(content.system!, input, snippets);
    userMessage = renderBody(content.user!, input, snippets);
    examples = renderExamples(
      content.examples!,
      content.user!,
      template,
      templates.tools,
    );
  } else {
    const { defaultContent, variants } = contents;
    const { variant } = input as unknown as { readonly variant: string };
    const variantContent = variants[variant]!;
    meta = (variantContent.meta ?? defaultContent.meta) as Meta;
    const system = (variantContent.system ?? defaultContent.system)!;
    const user = (variantContent.user ?? defaultContent.user)!;
    systemMessage = renderBody(system, input, snippets);
    userMessage = renderBody(user, input, snippets);
    examples = renderExamples(
      (variantContent.examples ?? defaultContent.examples)!,
      user,
      template,
      templates.tools,
    );
  }
  const tools = Object.fromEntries(
    template.tools.map(
      ({ id, name }): readonly [string, Tool<unknown, unknown>] => {
        const toolData = templates.tools[id]!;
        const toolSchemas = zodSchemas[id as keyof typeof zodSchemas]!;
        const tool: Tool<unknown, unknown> = {
          name: name,
          description: toolData.description,
          inputJsonSchema: toolData.inputJsonSchema as Record<string, unknown>,
          inputSchema: toolSchemas["input"],
          outputSchema: toolSchemas["output"],
        };
        return [name, tool];
      },
    ),
  ) as Tools<Id>;
  const isToolName = (name: string): name is ToolNames<Id> => {
    return name in tools;
  };
  const callTools = (
    calls: Iterable<ToolCall>,
    executor: ToolExecutor<Id>,
  ): Promise<ReadonlyArray<ToolCallResponse>> =>
    executeToolsImpl(calls, tools, executor);
  const outputFormat = (
    template.outputFormat === "json"
      ? {
          kind: "json",
          schema: outputSchema,
          jsonSchema: template.outputJsonSchema as Record<string, unknown>,
        }
      : { kind: "text" }
  ) as OutputFormat<Id>;
  const parseResponse = (c: string): Output<Id> =>
    parseResponseImpl(c, outputFormat);
  return {
    meta,
    systemMessage: systemMessage,
    userMessage: userMessage,
    examples,
    tools,
    isToolName,
    executeTools: callTools,
    outputFormat,
    parseResponse,
    templateId: templateId as Id,
    templateInput: input,
  };
}

function renderBody<Input>(
  body: Spec.Body,
  input: Input,
  snippets: { readonly [c: string]: Spec.Snippet },
): string {
  const renderPiece = (piece: Spec.BodyPiece): string => {
    switch (piece.kind) {
      case "text": {
        return piece.text;
      }
      case "insert-snippet": {
        const snippet = snippets[piece.snippet];
        if (!snippet) {
          throw new Error(`Snippet not found: ${piece.snippet}`);
        }
        return indent(renderSnippet(snippet, input, snippets), piece.indent);
      }
      case "insert-val": {
        const val = evaluate(input, piece.val);
        return indent(format(val, piece.format), piece.indent);
      }
    }
  };
  return body.map(renderPiece).join("");
}

function renderSnippet<Input>(
  snippet: Spec.Snippet,
  input: Input,
  snippets: { readonly [c: string]: Spec.Snippet },
): string {
  switch (snippet.kind) {
    case "snippet": {
      return renderBody(snippet.body, input, snippets);
    }
    case "snippet-if": {
      const { expression, then: thenBody, else: elseBody } = snippet;
      const evalResult = evaluate(input, expression);
      const condition = ((): boolean => {
        switch (snippet.is) {
          case "not-empty": {
            return (evalResult as { readonly length: number }).length >= 1;
          }
          case "not-null": {
            return evalResult !== undefined && evalResult !== null;
          }
          case "true": {
            return !!evalResult;
          }
        }
      })();
      const body = condition ? thenBody : elseBody;
      return renderBody(body, input, snippets);
    }
    case "snippet-switch": {
      const { expression, branches } = snippet;
      const evalResult = evaluate(input, expression);
      const branch = branches[evalResult as string];
      if (!branch) {
        throw new Error(`Branch not found: ${evalResult as string}`);
      }
      return renderBody(branch, input, snippets);
    }
  }
}

function indent(text: string, spaces: string): string {
  if (spaces.length <= 0) {
    return text;
  } else {
    return text.replace(/\n/g, "\n".concat(spaces));
  }
}

function evaluate<Input>(input: Input, expression: Spec.Expression): unknown {
  switch (expression.kind) {
    case "input": {
      return input;
    }
    case "property": {
      const { property } = expression;
      return (input as Record<string, unknown>)[property];
    }
  }
}

function renderExamples(
  inputs: readonly Spec.FewShotExample[],
  body: Spec.Body,
  template: Spec.Template,
  tools: { [id: string]: Spec.Tool },
): readonly FewShotExample[] {
  return inputs.map(({ input, output, intermediateSteps }) => ({
    userMessage: renderBody(body, input, template.snippets),
    intermediateSteps: intermediateSteps.map((step) => ({
      toolCalls: step.toolCalls.map((tc) => ({
        callId: tc.callId,
        toolName: tc.toolName,
        description: tools[tc.toolId]!.description,
        stringifiedInput: JSON.stringify(tc.input),
        stringifiedOutput: JSON.stringify(tc.output),
      })),
    })),
    response: format(output, template.outputFormat),
  }));
}

function format(input: unknown, format?: Spec.InsertFormat): string {
  switch (format) {
    case undefined:
    case "text": {
      return String(input);
    }
    case "json": {
      return JSON.stringify(input, undefined, 2);
    }
    case "yaml": {
      // Remove trailing newline if present.
      return YAML.stringify(input).replace(/\n$/, "");
    }
    case "toon": {
      return encodeToon(input);
    }
    case "csv":
    case "tsv": {
      const separator = format === "csv" ? "," : "\t";
      const array = input as ReadonlyArray<{ [k: string]: string | number }>;
      if (array.length <= 0) {
        return "";
      }
      const firstElement = array[0]!;
      const headerRow = Object.keys(firstElement).join(separator);
      const rows: string[] = [
        headerRow,
        ...array.map((e) => {
          return Object.values(e)
            .map((cell) => {
              const str = String(cell);
              if (separator === ",") {
                // CSV per RFC 4180: wrap in double quotes if the cell contains a
                // double quote, a comma, a newline, or a carriage return.
                return /[",\n\r]/.test(str)
                  ? '"'.concat(str.replace(/"/g, '""')).concat('"')
                  : str;
              } else {
                // TSV: no standard quoting; escape special characters with
                // backslash so the value remains a single field.
                return str
                  .replace(/\\/g, "\\\\")
                  .replace(/\t/g, "\\t")
                  .replace(/\n/g, "\\n")
                  .replace(/\r/g, "\\r");
              }
            })
            .join(separator);
        }),
      ];
      return rows.join("\n");
    }
  }
}

function parseResponseImpl<Id extends TemplateId>(
  response: string,
  outputFormat: OutputFormat<Id>,
): Output<Id> {
  switch (outputFormat.kind) {
    case "json": {
      response = response.trim();
      response = response.startsWith("```")
        ? response.replace(/^```(?:json)?\s*\n?([\s\S]*?)\n?```$/, "$1").trim()
        : response;
      return outputFormat.schema.parse(JSON.parse(response));
    }
    case "text": {
      return response as unknown as Output<Id>;
    }
  }
}

function uncapitalize(name: string): string {
  return name[0]!.toLowerCase().concat(name.slice(1));
}

/** Entry point for building prompts. */
export const prompts = newPromptsImpl(TEMPLATES_DATA);
